"""Saved-only source-bound measurements for one original crest attempt."""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

from saved_crest_finalizer import finalize


def _source(root, name):
    path = root / name
    if not path.is_file():
        raise ValueError('Missing required source: ' + name)
    return path


def _sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def _rows(path):
    return [json.loads(row) for row in path.read_text(encoding='utf-8').splitlines()]


def _write(path, value):
    Path(path).write_text(json.dumps(value, sort_keys=True, allow_nan=False) + '\n', encoding='utf-8')


def measure_limit(capture, finalized):
    packet = json.loads(_source(capture, 'reviewed-limit.json').read_text(encoding='utf-8'))
    return {'prescribed_limit_mps': packet['prescribed_limit_mps'],
            'road_id': packet['road_id'], 'source_kind': packet['source_kind'],
            'source_sha256': _sha(capture / 'reviewed-limit.json')}


def measure_crest(capture, finalized):
    return {'crossing': finalized['crest_crossing'],
            'native_map_sha256': finalized['native_map_sha256']
            if 'native_map_sha256' in finalized else
            json.loads(_source(capture, 'crest-manifest.json').read_text())['native_map_sha256']}


def measure_speed(capture, finalized):
    return dict(finalized['speed_profile_witness'])


def measure_other(capture, finalized):
    motion = json.loads(_source(capture, 'motion.json').read_text(encoding='utf-8'))
    if len(motion) != 900:
        raise ValueError('original other vehicle history incomplete')
    actor_ids = {row['other_actor_id'] for row in motion}
    if len(actor_ids) != 1:
        raise ValueError('original other vehicle identity differs')
    return {'actor_id': next(iter(actor_ids)),
            'first_station_m': motion[0]['other_s_m'],
            'last_station_m': motion[-1]['other_s_m'],
            'minimum_body_clearance_m': min(row['body_clearance_m'] for row in motion),
            'observed_frames': len(motion)}


MEASUREMENTS = {
    'prescribed_limit_measurement': (measure_limit, ['capture/crest-source/reviewed-limit.json', 'capture/crest-source/context.json']),
    'crest_measurement': (measure_crest, ['capture/crest-source/grade.json', 'capture/crest-source/native-map.xodr', 'capture/crest-source/motion.json']),
    'speed_decrease_measurement': (measure_speed, ['capture/crest-source/motion.json', 'capture/crest-source/context.json']),
    'other_vehicle_measurement': (measure_other, ['capture/crest-source/motion.json', 'capture/crest-source/other-route.json']),
}


def analyze(attempt, output):
    attempt = Path(attempt)
    output = Path(output)
    config = json.loads(_source(attempt, 'config.json').read_text(encoding='utf-8'))
    case_id = config['selected_case_id']
    capture = attempt / 'capture/crest-source'
    manifest = json.loads(_source(capture, 'crest-manifest.json').read_text(encoding='utf-8'))
    for _, names in MEASUREMENTS.values():
        for name in names:
            _source(attempt, name)
    for name in ('trace.jsonl', 'video_frames.jsonl', 'capture/evidence.jsonl'):
        _source(attempt, name)
    finalized = finalize(capture, manifest, expected_case=case_id)
    motion = json.loads(_source(capture, 'motion.json').read_text(encoding='utf-8'))
    mapping = _rows(_source(attempt, 'video_frames.jsonl'))
    trace = _rows(_source(attempt, 'trace.jsonl'))
    if len(motion) != len(mapping) or len(trace) != len(mapping) or len(mapping) != 900:
        raise ValueError('original motion, trace and camera coverage differ')
    if any(m['frame_id'] != f['carla_frame'] or t['frame'] != f['carla_frame']
           or m['time_s'] != f['time_s'] or t['time_s'] != f['time_s']
           for m, t, f in zip(motion, trace, mapping)):
        raise ValueError('original Native frame/time join differs')
    measurements = {}
    for key, (method, names) in MEASUREMENTS.items():
        paths = {name: _source(attempt, name) for name in names}
        measurements[key] = {'value': method(capture, finalized),
                             'method': method.__name__,
                             'sources': {name: _sha(path) for name, path in paths.items()}}
    channels = attempt / 'channels'
    channels.mkdir(exist_ok=False)
    evidence = []
    description = config['case']['recording_description']
    views = {
        'native_grade': [row['position']['z'] for row in trace],
        'precrest_speed': [row['ego_speed_mps'] for row in motion],
        'other_vehicle': [row['body_clearance_m'] for row in motion],
        'prescribed_limit': [measurements['prescribed_limit_measurement']['value']['prescribed_limit_mps']] * 900,
        'camera_frame_map': [{'video_frame': row['video_frame'],
                              'carla_frame': row['carla_frame']} for row in mapping],
    }
    for channel in description['channels']:
        name = channel['name']
        path = channels / (name + '.jsonl')
        with path.open('x', encoding='utf-8') as stream:
            for identity, value in zip(mapping, views[name]):
                stream.write(json.dumps({'time_s': identity['time_s'], 'value': value},
                                        allow_nan=False) + '\n')
        evidence.append({'name': name, 'unit': channel['unit'],
                         'reference': 'channels/' + path.name})
    context_name = 'reviewed_original_crest_site'
    context_path = channels / (context_name + '.json')
    _write(context_path, {context_name: {
        'limit_sha256': _sha(capture / 'reviewed-limit.json'),
        'native_map_sha256': _sha(capture / 'native-map.xodr'),
        'capture_ref': manifest['native_capture_ref']}})
    evidence.append({'name': context_name, 'unit': 'structured record',
                     'reference': 'channels/' + context_path.name})
    witness = finalized['speed_profile_witness']
    target = {'target': 'selected_precrest_speed_profile', 'requested': True,
              'measured': True, 'method': 'source-bound full-frame original speed and station witness',
              'tolerance': 0, 'matched': True, 'physical_cause_confirmed': False,
              'cause_evidence': 'Original timing observed; physical necessity and legal duty remain for review'}
    result = {'case_id': case_id, 'measured_values': measurements,
              'target_checks': [target], 'setup_confirmed': True,
              'behavior_attempted': True, 'maneuver_completed': True,
              'termination_reason': 'original 900-frame hill crest passage and saved profile finalized',
              'physical_failure_flags': {}, 'trace_reference': 'trace.jsonl',
              'video_references': ['overview.mkv', 'approach.mkv',
                                   'reference_corner.mkv', 'driver_reference.mkv'],
              'video_frame_map_reference': 'video_frames.jsonl',
              'recording_description': description, 'recording_evidence': evidence,
              'realized_observables': {}, 'physical_acceptance_claimed': False,
              'legal_acceptance_claimed': False,
              'original_source_manifest_sha256': _sha(capture / 'crest-manifest.json'),
              'speed_profile_witness': witness}
    _write(attempt / 'result.json', result)
    report = {'format': 'worker-analysis-report', 'case_id': case_id,
              'measurements': measurements, 'source_manifest_sha256':
              result['original_source_manifest_sha256'],
              'analysis_complete': True,
              'limitations': ['Physical necessity, lawful entry and due care require independent review; no legal verdict.']}
    _write(output, report)
    return report


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--attempt', required=True)
    parser.add_argument('--output', required=True)
    args = parser.parse_args()
    analyze(args.attempt, args.output)


if __name__ == '__main__':
    main()

"""Survey an original Native two-way crest without importing CARLA.

The caller supplies CARLA waypoints from the selected map. This is a construction
preflight, not evidence that a later vehicle followed the route or saw its peer.
"""
from __future__ import annotations

import hashlib
import math

from crest_speed import crest_station


def _position(waypoint):
    location = waypoint.transform.location
    values = (location.x, location.y, location.z)
    if not all(type(value) in (int, float) and math.isfinite(value) for value in values):
        raise ValueError('finite original waypoint location required')
    return tuple(float(value) for value in values)


def survey_lane(start, *, map_name, map_sha256, step_m=5.0, count=9):
    """Follow one unbranched driving lane and return source-bound grade samples."""
    if not map_name or not isinstance(map_sha256, str) or len(map_sha256) != 64:
        raise ValueError('source-bound original map identity required')
    if type(step_m) not in (int, float) or not math.isfinite(step_m) or step_m <= 0:
        raise ValueError('positive finite waypoint step required')
    if type(count) is not int or count < 5:
        raise ValueError('five or more original route waypoints required')
    road_id, lane_id = start.road_id, start.lane_id
    if lane_id == 0 or not str(start.lane_type).lower().endswith('driving'):
        raise ValueError('original driving lane required')
    waypoints = [start]
    for _ in range(count - 1):
        choices = waypoints[-1].next(float(step_m))
        if len(choices) != 1:
            raise ValueError('original route must have one connected continuation')
        next_waypoint = choices[0]
        if next_waypoint.road_id != road_id or next_waypoint.lane_id != lane_id:
            raise ValueError('route changed original road or lane')
        waypoints.append(next_waypoint)
    points = [_position(waypoint) for waypoint in waypoints]
    grades = []
    station = 0.0
    for index, (waypoint, point) in enumerate(zip(waypoints, points)):
        if index:
            previous = points[index - 1]
            segment = math.dist(point, previous)
            if segment <= 0 or segment > 2 * step_m:
                raise ValueError('original route has a gap or duplicate waypoint')
            station += segment
        grades.append({'s_m': station, 'z_m': point[2],
                       'source_ref': f'{map_name}:{map_sha256}:{road_id}:{lane_id}:{waypoint.s}',
                       'x_m': point[0], 'y_m': point[1]})
    peak = crest_station(grades)
    peak_point = min(grades, key=lambda point: abs(point['s_m'] - peak))
    return {'map_name': map_name, 'map_sha256': map_sha256,
            'road_id': road_id, 'lane_id': lane_id,
            'waypoints': grades, 'crest_station_m': peak,
            'crest_world_xyz_m': [peak_point['x_m'], peak_point['y_m'], peak_point['z_m']]}


def bind_opposing_routes(forward, opposing, *, max_crest_separation_m=20.0):
    """Require two original directions of one road with colocated grade crests."""
    if forward['map_sha256'] != opposing['map_sha256'] or forward['map_name'] != opposing['map_name']:
        raise ValueError('opposing routes use different original maps')
    if forward['road_id'] != opposing['road_id'] or forward['lane_id'] * opposing['lane_id'] >= 0:
        raise ValueError('opposing routes must use opposite driving lanes of one road')
    distance = math.dist(forward['crest_world_xyz_m'], opposing['crest_world_xyz_m'])
    if distance > max_crest_separation_m:
        raise ValueError('opposing original grade crests are not colocated')
    return {'map_sha256': forward['map_sha256'], 'road_id': forward['road_id'],
            'forward_lane_id': forward['lane_id'], 'opposing_lane_id': opposing['lane_id'],
            'crest_separation_m': distance,
            'limitation': 'Waypoints establish route geometry only; sight lines and actual motion need capture.'}


def survey_map_pair(carla_map, forward_start, opposing_start, *, expected_map_sha256,
                    step_m=5.0, count=9):
    """Hash the actual Native OpenDRIVE text before binding either direction."""
    source = carla_map.to_opendrive()
    if not isinstance(source, str) or not source.strip():
        raise ValueError('original Native OpenDRIVE source required')
    actual_sha256 = hashlib.sha256(source.encode('utf-8')).hexdigest()
    if actual_sha256 != expected_map_sha256:
        raise ValueError('original Native map source hash differs')
    map_name = carla_map.name
    forward = survey_lane(forward_start, map_name=map_name,
                          map_sha256=actual_sha256, step_m=step_m, count=count)
    opposing = survey_lane(opposing_start, map_name=map_name,
                           map_sha256=actual_sha256, step_m=step_m, count=count)
    binding = bind_opposing_routes(forward, opposing)
    return {'forward': forward, 'opposing': opposing, 'binding': binding}

"""Assess observed crest passage from original station and frame samples.

This is an engineering event check. It does not establish sight, due care,
collision avoidance, or the legally necessary amount of slowing.
"""
from __future__ import annotations

import math

from crest_speed import crest_station


def assess(waypoints, frames, *, approach_start_m):
    crest_s = crest_station(waypoints)
    if type(approach_start_m) not in (int, float) or not math.isfinite(approach_start_m):
        raise ValueError('finite approach start required')
    if approach_start_m >= crest_s:
        raise ValueError('approach must start before original crest')
    if not isinstance(frames, list) or len(frames) < 3:
        raise ValueError('original motion frames required')
    previous = None
    approached = None
    crossing = None
    postcrest = None
    for frame in frames:
        if not isinstance(frame, dict) or type(frame.get('frame_id')) is not int:
            raise ValueError('original frame identity required')
        station = frame.get('ego_s_m')
        time = frame.get('time_s')
        if not all(type(value) in (int, float) and math.isfinite(value)
                   for value in (station, time)) or not frame.get('source_ref'):
            raise ValueError('source-bound finite original station and time required')
        if previous is not None:
            if frame['frame_id'] <= previous['frame_id'] or time <= previous['time_s']:
                raise ValueError('original frame order differs')
            if station < previous['ego_s_m']:
                raise ValueError('original ego station reversed')
        if approached is None and approach_start_m <= station < crest_s:
            approached = frame
        if approached is not None and crossing is None and station >= crest_s:
            crossing = frame
        elif crossing is not None and postcrest is None and station > crest_s:
            postcrest = frame
        previous = frame
    if approached is None or crossing is None or postcrest is None:
        raise ValueError('original approach, crest crossing and postcrest samples required')
    return {
        'crest_station_m': crest_s,
        'first_approach_frame_id': approached['frame_id'],
        'crossing_frame_id': crossing['frame_id'],
        'crossing_time_s': crossing['time_s'],
        'crossing_station_m': crossing['ego_s_m'],
        'first_postcrest_frame_id': postcrest['frame_id'],
        'source_refs': [approached['source_ref'], crossing['source_ref'],
                        postcrest['source_ref']],
        'interpretation_limit': 'Observed station passage only; physical visibility, collision avoidance and legal duty remain unjudged.',
    }

"""Lazy, station-bound engineering speed profiles for the exact crest cases.

Targets distinguish physical constructions. Actual original Native speed history
must be measured independently by crest_speed.py before any case comparison.
"""
from __future__ import annotations

import math


PROFILES = {
    'early_decrease': ((30.0, 12.0), (20.0, 10.0), (10.0, 8.0), (0.0, 8.0)),
    'late_decrease': ((30.0, 12.0), (20.0, 12.0), (10.0, 10.0), (0.0, 8.0)),
    'steady_approach': ((30.0, 12.0), (20.0, 12.0), (10.0, 12.0), (0.0, 12.0)),
}


def target_speed(profile, *, crest_s_m, ego_s_m):
    if profile not in PROFILES:
        raise ValueError('unknown exact speed profile')
    if not all(type(x) in (float, int) and math.isfinite(x) for x in (crest_s_m, ego_s_m)):
        raise ValueError('finite original crest and ego stations required')
    distance = crest_s_m - ego_s_m
    if distance < 0:
        return PROFILES[profile][-1][1]
    for threshold, target in PROFILES[profile]:
        if distance >= threshold:
            return target
    return PROFILES[profile][-1][1]


def step(vehicle, command_factory, profile, *, crest_s_m, ego_s_m, measured_speed_mps,
         steer=0.0, route_end_s_m=None):
    """Apply one CARLA-compatible control without importing CARLA at module load."""
    if type(measured_speed_mps) not in (float, int) or not math.isfinite(measured_speed_mps) or measured_speed_mps < 0:
        raise ValueError('original measured speed required')
    target = target_speed(profile, crest_s_m=crest_s_m, ego_s_m=ego_s_m)
    if route_end_s_m is not None:
        if (type(route_end_s_m) not in (float, int) or
                not math.isfinite(route_end_s_m) or route_end_s_m <= crest_s_m):
            raise ValueError('source-bound route end must follow crest')
        if ego_s_m >= route_end_s_m - 20.0:
            target = 0.0
    error = target - measured_speed_mps
    throttle = min(0.55, max(0.0, 0.18 * error))
    brake = min(0.65, max(0.0, -0.22 * error))
    command = command_factory(throttle=throttle, brake=brake, steer=steer)
    vehicle.apply_control(command)
    return {'target_speed_mps': target, 'measured_speed_mps': measured_speed_mps,
            'throttle': throttle, 'brake': brake,
            'limitation': 'Command output and route-end stop are engineering requests, not evidence of actual slowing or legal necessity.'}

"""Independent physical comparison of two source-bound crest speed packets."""
from __future__ import annotations

from crest_speed import measure


FIXED = ('map_source_sha256', 'ego_route_source_sha256',
         'other_route_source_sha256', 'other_motion_source_sha256',
         'highway_context_source_sha256', 'prescribed_limit_source_sha256',
         'camera_contract_sha256', 'duration_s')


def compare(left, right, *, expected_profiles):
    if not isinstance(left, dict) or not isinstance(right, dict):
        raise ValueError('two original capture packets required')
    if [left.get('profile'), right.get('profile')] != list(expected_profiles):
        raise ValueError('exact comparison profiles differ')
    for field in FIXED:
        if left.get(field) is None or left.get(field) != right.get(field):
            raise ValueError(f'fixed condition differs or is missing: {field}')
    if left.get('capture_id') == right.get('capture_id') or not all(
            packet.get('capture_id') for packet in (left, right)):
        raise ValueError('two distinct original captures required')
    measured = [measure(packet.get('waypoints'), packet.get('frames'),
                        approach_start_m=packet.get('approach_start_m'))
                for packet in (left, right)]
    if any(m['initial_speed_mps'] != packet.get('initial_speed_mps')
           for m, packet in zip(measured, (left, right))):
        raise ValueError('declared initial speed differs from original motion')
    if abs(measured[0]['initial_speed_mps'] - measured[1]['initial_speed_mps']) > 0.5:
        raise ValueError('fixed initial approach speed differs beyond engineering band')
    if measured[0]['crest_station_m'] != measured[1]['crest_station_m']:
        raise ValueError('measured crest station differs')
    if measured[0]['speed_change_mps'] == measured[1]['speed_change_mps'] and \
            measured[0]['first_speed_decrease_frame_id'] == measured[1]['first_speed_decrease_frame_id']:
        raise ValueError('declared speed-profile difference was not measured')
    return {'comparison_profiles': list(expected_profiles),
            'capture_ids': [left['capture_id'], right['capture_id']],
            'physical_measurements': measured,
            'legal_limit': 'No conclusion on necessary decrease, due care or compliance.'}
